import React, { useState, useEffect } from 'react';
import { Navigate, Routes, Route } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import HomePage from './pages/HomePage';
import FocusPage from './pages/FocusPage';
import QuizPage from './pages/QuizPage';
import FlashcardsPage from './pages/FlashcardsPage';
import SettingsPage from './pages/SettingsPage';
import DoubtChatPage from './pages/DoubtChatPage';
import LoginPage from './pages/LoginPage';
import SignupPage from './pages/SignupPage';
import ProtectedRoute from './components/ProtectedRoute';

import { useAuth } from './context/AuthContext';

const App: React.FC = () => {
    const [theme, setTheme] = useState('light');
    const { isAuthenticated, isLoading } = useAuth();

    const toggleTheme = () => {
        setTheme(theme === 'light' ? 'dark' : 'light');
    };

    useEffect(() => {
        document.body.setAttribute('data-bs-theme', theme);
    }, [theme]);

    if (isLoading) {
        return (
            <div className="app-loading">
                <div className="loading-card">
                    <div className="loading-mark" />
                    <span>Loading your workspace...</span>
                </div>
            </div>
        );
    }

    return (
        <div className={isAuthenticated ? "app-shell" : "auth-shell"}>
            {isAuthenticated && <Sidebar toggleTheme={toggleTheme} />}
            <main className={isAuthenticated ? "app-main" : "auth-main"}>
                <Routes>
                    <Route
                        path="/login"
                        element={isAuthenticated ? <Navigate to="/" replace /> : <LoginPage />}
                    />
                    <Route
                        path="/signup"
                        element={isAuthenticated ? <Navigate to="/" replace /> : <SignupPage />}
                    />
                    <Route path="/" element={<ProtectedRoute><HomePage /></ProtectedRoute>} />
                    <Route path="/focus" element={<ProtectedRoute><FocusPage /></ProtectedRoute>} />
                    <Route path="/quizzes" element={<ProtectedRoute><QuizPage /></ProtectedRoute>} />
                    <Route path="/flashcards" element={<ProtectedRoute><FlashcardsPage /></ProtectedRoute>} />
                    <Route path="/chat" element={<ProtectedRoute><DoubtChatPage /></ProtectedRoute>} />
                    <Route path="/settings" element={<ProtectedRoute><SettingsPage /></ProtectedRoute>} />
                </Routes>
            </main>
        </div>
    );
};

export default App;
