import React, { useState, useEffect, useCallback } from 'react';
import { Button, Form, InputGroup } from 'react-bootstrap';
import { useAuth } from '../context/AuthContext';
import { apiFetch } from '../api';

const PomodoroTimer: React.FC = () => {
    const { user, updateUser } = useAuth();

    const [workDuration, setWorkDuration] = useState(() => {
        const storedWork = localStorage.getItem('pomodoroWorkDuration');
        return storedWork ? parseInt(storedWork) : 25;
    });
    const [breakDuration, setBreakDuration] = useState(() => {
        const storedBreak = localStorage.getItem('pomodoroBreakDuration');
        return storedBreak ? parseInt(storedBreak) : 5;
    });

    const [minutes, setMinutes] = useState(workDuration);
    const [seconds, setSeconds] = useState(0);
    const [isActive, setIsActive] = useState(false);
    const [timerType, setTimerType] = useState<'pomodoro' | 'break'>('pomodoro'); // 'pomodoro' or 'break'

    useEffect(() => {
        setMinutes(timerType === 'pomodoro' ? workDuration : breakDuration);
        setSeconds(0);
    }, [timerType, workDuration, breakDuration]);

    useEffect(() => {
        localStorage.setItem('pomodoroWorkDuration', workDuration.toString());
        localStorage.setItem('pomodoroBreakDuration', breakDuration.toString());
    }, [workDuration, breakDuration]);

    const handleSessionComplete = useCallback(async () => {
        if (!user) return;

        try {
            const response = await apiFetch('/api/pomodoro/complete', {
                method: 'POST',
                body: JSON.stringify({}),
            });
            const data = await response.json();
            if (response.ok) {
                updateUser({
                    coins: data.coins,
                    xp: data.xp,
                    streak: data.streak,
                });
                const earnedCoins = data.rewards?.coins ?? 25;
                const earnedXp = data.rewards?.xp ?? 50;
                alert(`Great job! You earned ${earnedCoins} coins and ${earnedXp} XP.`);
            }
        } catch (error) {
            console.error("Failed to update user stats:", error);
        }
    }, [user, updateUser]);

    useEffect(() => {
        let interval: NodeJS.Timeout | null = null;

        if (isActive) {
            interval = setInterval(() => {
                if (seconds > 0) {
                    setSeconds(seconds - 1);
                } else if (minutes > 0) {
                    setMinutes(minutes - 1);
                    setSeconds(59);
                } else {
                    // Timer finished
                    if (timerType === 'pomodoro') {
                        handleSessionComplete();
                        setTimerType('break');
                        alert('Time for a break!');
                    } else {
                        setTimerType('pomodoro');
                        alert('Break is over! Back to work.');
                    }
                    setIsActive(false);
                }
            }, 1000);
        } else if (!isActive && seconds !== 0) {
            if(interval) clearInterval(interval);
        }
        return () => {
            if(interval) clearInterval(interval)
        };
    }, [isActive, seconds, minutes, timerType, workDuration, breakDuration, user, updateUser, handleSessionComplete]);

    const toggle = () => {
        setIsActive(!isActive);
    };

    const reset = () => {
        setIsActive(false);
        setTimerType('pomodoro');
        setMinutes(workDuration);
        setSeconds(0);
    };

    const handleWorkDurationChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = parseInt(e.target.value);
        if (!isNaN(value) && value > 0) {
            setWorkDuration(value);
            if (!isActive && timerType === 'pomodoro') setMinutes(value);
        }
    };

    const handleBreakDurationChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = parseInt(e.target.value);
        if (!isNaN(value) && value > 0) {
            setBreakDuration(value);
            if (!isActive && timerType === 'break') setMinutes(value);
        }
    };

    return (
        <section className="tool-panel timer-panel">
            <div className="section-title">
                <span className="eyebrow">Timer</span>
                <h2>Pomodoro Timer</h2>
            </div>
            <div className="duration-grid">
                <InputGroup>
                    <InputGroup.Text>Work (min)</InputGroup.Text>
                    <Form.Control
                        type="number"
                        value={workDuration}
                        onChange={handleWorkDurationChange}
                        min="1"
                        disabled={isActive}
                    />
                </InputGroup>
                <InputGroup>
                    <InputGroup.Text>Break (min)</InputGroup.Text>
                    <Form.Control
                        type="number"
                        value={breakDuration}
                        onChange={handleBreakDurationChange}
                        min="1"
                        disabled={isActive}
                    />
                </InputGroup>
            </div>
            <div className="timer-display">
                {minutes < 10 ? `0${minutes}` : minutes}:{
                seconds < 10 ? `0${seconds}` : seconds}
            </div>
            <div className="button-row">
                <Button onClick={toggle} variant={isActive ? 'warning' : 'primary'}>
                    {isActive ? 'Pause' : 'Start'}
                </Button>
                <Button onClick={reset} variant="secondary">
                    Reset
                </Button>
            </div>
        </section>
    );
};

export default PomodoroTimer;
